<script lang="ts" setup>
import { useId } from 'vue'

// The EJ badge at icon size — the stamp identity reduced to what survives 16-24px: a solid tilted
// square with the monogram knocked out, drawn rather than set. Source and reasoning:
// docs/branding/mark-proposal-ej-badge-small.svg and docs/BRANDING.md §4b.
//
// The letters are hand-drawn paths, NOT type. Rubik Distressed — the display face — is illegible
// below ~96px, so the icon rung needs simplified letterforms. That also keeps this font-free, which
// favicon.svg needs because browsers are served the SVG itself.
//
// Decorative: the adjacent wordmark carries the accessible name, so this is aria-hidden.
// Size it with a height utility (e.g. `h-6`).

// Unique mask id per instance — two badges on one page sharing one id renders the second as a solid
// block. The header and the footer are two.
const maskId = useId()
